/* Generated by tools/mkpen.py from the original's own settings. */
#ifndef JW_PENS_H
#define JW_PENS_H

/* The ten screen pens, as 0x00rrggbb.  The registry keeps them the
 * way GDI does, 0x00bbggrr, under Pen/ColorNN. */
static const unsigned int jw_default_pen_rgb[10] = {
    0xffffffu,
    0x00c0c0u,
    0x000000u,
    0x00c000u,
    0xc0c000u,
    0xc000c0u,
    0x0000ffu,
    0x008080u,
    0xff0080u,
    0xff80ffu,
};

static const int jw_default_pen_width[10] = {
    1, 1, 1, 1, 1, 1, 2, 3, 5, 1
};

/* Two colours that are in no drawing.  The colour page of
 * the basic-settings dialog names them: Color10 is the one a
 * picked element gets and Color11 the provisional one.
 *
 * The original bears both out, with its window painted into an
 * off-screen bitmap rather than read off the screen.  A range
 * dragged over Test5 has its picked lines in ff00ff and its box
 * in ff0000, and **a figure the command is part way through is
 * ff0000 too** -- a rectangle with one corner down, a line with
 * one end down and a circle with its centre down all came back
 * drawn in it (tools/probe75.sh).  So the range box and the
 * provisional figure are the one colour, which is what the
 * second of those two settings is called. */
#define JW_SEL_RGB    0xff00ffu
#define JW_KARI_RGB   0xff0000u
#define JW_RANGE_RGB  JW_KARI_RGB

/* A drawing that has just been started.  The status line of
 * docs/ref_start.png reads "A-2  S=1/100  [0-0]", which is these
 * three: sheet index 2, the write group's scale, and group 0 /
 * layer 0 being the ones written to. */
#define JW_NEW_PAPER  2
#define JW_NEW_SCALE  100
#define JW_NEW_LAYER  0

#endif
